import itertools
import networkx as nx

def get_diameter(N):
    perms = list(itertools.permutations(range(N)))
    cosets = []
    visited = set()
    for p in perms:
        if p in visited:
            continue
        coset = []
        curr = p
        for _ in range(N):
            coset.append(curr)
            visited.add(curr)
            curr = tuple(curr[(i + 1) % N] for i in range(N))
        cosets.append(tuple(coset))
    G = nx.Graph()
    for i in range(len(cosets)):
        G.add_node(i)
    for i, coset in enumerate(cosets):
        rep = coset[0]
        for j in range(N):
            lst = list(rep)
            lst[j], lst[(j + 1) % N] = lst[(j + 1) % N], lst[j]
            new_p = tuple(lst)
            for k, other_coset in enumerate(cosets):
                if new_p in other_coset:
                    G.add_edge(i, k)
                    break
    return nx.diameter(G)

print(f"N=7, diameter={get_diameter(7)}")

import itertools
import networkx as nx

def get_diameter(N):
    perms = list(itertools.permutations(range(N)))
    cosets = []
    visited = set()
    for p in perms:
        if p in visited:
            continue
        coset = []
        curr = p
        for _ in range(N):
            coset.append(curr)
            visited.add(curr)
            curr = tuple(curr[(i + 1) % N] for i in range(N))
        cosets.append(tuple(coset))

    # Optimization: Use a dictionary to map each permutation to its coset index.
    perm_to_coset = {}
    for i, coset in enumerate(cosets):
        for p in coset:
            perm_to_coset[p] = i

    G = nx.Graph()
    for i in range(len(cosets)):
        G.add_node(i)
    for i, coset in enumerate(cosets):
        rep = coset[0]
        for j in range(N):
            lst = list(rep)
            lst[j], lst[(j + 1) % N] = lst[(j + 1) % N], lst[j]
            new_p = tuple(lst)
            G.add_edge(i, perm_to_coset[new_p])

    return nx.diameter(G)

print(f"N=8, diameter={get_diameter(8)}")

